  );
  expect(blurMatch, 'blur handler not found').to.not.be.null;

  const blurBody = blurMatch[1];

  // The blur handler must NOT call editTodo unconditionally. There must be a guard:
  // a conditional check before editTodo is invoked that prevents calling it when
  // keydown has already processed the same edit action.
  //
  // A valid guard pattern: a flag variable (e.g. "justHandled", "enterProcessed",
  // "skipBlur") is set in the keydown handler and checked in the blur handler before
  // calling editTodo.
  //
  // Find all editTodo calls in the blur body and check that each is inside a conditional
  // that guards against re-processing.
  const lines = blurBody.split('\n').map(l => l.trim()).filter(l => l.length > 0);

  // Find the line index of the editTodo call
  const editTodoLineIdx = lines.findIndex(l => /editTodo\s*\(/.test(l));
