  // classList.contains('edit') check (that's the baseline edit-input filter, not the guard).
  // The guard must reference some state that tracks whether keydown already handled the action.
  const precedingLines = lines.slice(0, editTodoLineIdx);
  const ifLines = precedingLines.filter(l => /^if\s*\(/.test(l));

