  const blurMatch = source.match(
    /addEventListener\s*\(\s*['"]blur['"][^)]*\)\s*\{([\s\S]*?\})\s*\},\s*true\s*\)/
  );
  expect(blurMatch, 'blur handler not found').to.not.be.null;

  const blurBody = blurMatch[1];

  // The blur handler must NOT call editTodo unconditionally. There must be a guard that
  // checks a flag set by the keydown handler, preventing re-processing when Enter already
  // handled the edit.
  //
  // A valid guard references a variable that tracks keydown-handled state — something like
  // "justHandled", "enterProcessed", "skipBlur", "lastAction", etc. It must NOT be a
  // local DOM variable, a null guard, or a DOM property check.

  // Find all if-conditions in the blur body that precede the editTodo call.
  const lines = blurBody.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  const editTodoLineIdx = lines.findIndex(l => /editTodo\s*\(/.test(l));
  expect(editTodoLineIdx, 'editTodo call not found in blur handler').to.be.greaterThan(-1);

  const precedingLines = lines.slice(0, editTodoLineIdx);
  const ifLines = precedingLines.filter(l => /^if\s*\(/.test(l));

  // Filter out:
  // - DOM property checks (classList, tagName, className, getAttribute)
  // - Null/undefined guards (if (!var) return)
  // - typeof checks
  const flagGuardLines = ifLines.filter(l => {
    // Skip DOM property checks
    if (/classList|tagName|className|getAttribute/.test(l)) return false;
    // Skip null/undefined guards: if (!something) or if (something == null)
    if (/^if\s*\(\s*!?\s*\w+(\s*[!=]==?\s*(null|undefined))?\s*\)\s*(return|throw)/.test(l)) return false;
    // Skip typeof checks
    if (/typeof\s+/.test(l)) return false;
    return true;
