  // it's a shared state between keydown and blur.
  const keydownMatch = source.match(
    /addEventListener\s*\(\s*['"]keydown['"][^)]*\)\s*\{([\s\S]*?\})\s*\}\s*\)/
  );
  expect(keydownMatch, 'keydown handler not found').to.not.be.null;

  const keydownBody = keydownMatch[1];

  // Extract variable names from the guard conditions
  for (const guardLine of flagGuardLines) {
    // Try to find the variable name in the if-condition
    const varMatch = guardLine.match(/if\s*\(\s*(?:!?\s*)?(\w+)/);
    if (varMatch) {
      const varName = varMatch[1];
      // The variable should appear in the keydown handler body
      const inKeydown = new RegExp('\\b' + varName + '\\b').test(keydownBody);
      if (inKeydown) {
        return; // Found a valid guard: flag variable used in both blur and keydown
      }
    }
  }

  // If we get here, none of the guard variables were found in keydown
  throw new Error(
    'blur handler guard variable not found in keydown handler — ' +
    'the guard must reference shared state that the keydown handler sets. ' +
    'Guard conditions found: ' + JSON.stringify(flagGuardLines)
  );
});

